// REQ-001, AC-001, GAP-001; Native mappings: UC-D-001, UC-D-002, UC-D-003.
'use strict';
const assert = require('node:assert/strict');
const http = require('node:http');
const { spawn } = require('node:child_process');
const path = require('node:path');
const { exportOrders } = require('../src/orders.cjs');

function request(base, route, timeoutMs = 3000) {
  return new Promise((resolve, reject) => {
    const req = http.get(base + route, res => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { body += chunk; });
      res.on('error', reject);
      res.on('end', () => {
        if (res.statusCode !== 200) {
          const error = new Error('Upstream HTTP ' + res.statusCode);
          error.statusCode = res.statusCode;
          reject(error);
          return;
        }
        try { resolve(JSON.parse(body)); } catch (error) { reject(error); }
      });
    });
    req.setTimeout(timeoutMs, () => {
      const error = new Error('Real upstream request timed out after ' + timeoutMs + 'ms');
      error.code = 'UPSTREAM_TIMEOUT';
      req.destroy(error);
    });
    req.on('error', reject);
  });
}

async function withServer(run) {
  const child = spawn(process.execPath, [path.join(__dirname, '../pilot/server.cjs')], {
    cwd: path.join(__dirname, '..'),
    env: { ...process.env, PILOT_PORT: '0' },
    stdio: ['ignore', 'pipe', 'pipe']
  });
  let stderr = '';
  child.stderr.setEncoding('utf8');
  child.stderr.on('data', chunk => { stderr += chunk; });
  const exited = new Promise(resolve => child.once('exit', (code, signal) => resolve({ code, signal })));
  try {
    const address = await new Promise((resolve, reject) => {
      let output = '';
      const timer = setTimeout(() => reject(new Error('Local upstream startup timed out: ' + stderr)), 5000);
      const finish = (error, value) => {
        clearTimeout(timer);
        child.stdout.removeListener('data', onData);
        child.removeListener('error', onError);
        child.removeListener('exit', onExit);
        if (error) reject(error); else resolve(value);
      };
      const onError = error => finish(error);
      const onExit = code => finish(new Error('Local upstream exited before readiness: ' + code + ' ' + stderr));
      const onData = chunk => {
        output += chunk;
        const end = output.indexOf('\n');
        if (end < 0) return;
        try { finish(null, JSON.parse(output.slice(0, end))); } catch (error) { finish(error); }
      };
      child.stdout.setEncoding('utf8');
      child.stdout.on('data', onData);
      child.once('error', onError);
      child.once('exit', onExit);
    });
    const base = 'http://127.0.0.1:' + address.port;
    const version = await request(base, '/version');
    assert.equal(version.ready, true);
    assert.equal(version.version_digest, 'p110-upstream-v1');
    assert.equal(version.owner, 'internal-pilot');
    assert.equal(version.candidate_commit, address.candidate_commit);
    await run(base);
  } finally {
    if (child.exitCode === null && child.signalCode === null) child.kill('SIGTERM');
    let timer;
    try {
      await Promise.race([
        exited,
        new Promise((resolve, reject) => {
          timer = setTimeout(() => {
            child.kill('SIGKILL');
            reject(new Error('Local upstream did not stop within 5 seconds'));
          }, 5000);
        })
      ]);
    } finally { clearTimeout(timer); }
  }
}

function upstreamFor(base, count) {
  const state = { calls: 0, rows: undefined };
  state.fetch = async () => {
    state.calls += 1;
    state.rows = await request(base, '/upstream?count=' + count);
    return state.rows;
  };
  return state;
}

async function successfulExport(state, label) {
  let pages;
  await assert.doesNotReject(async () => { pages = await exportOrders(state.fetch); }, label);
  assert.equal(state.calls, 1, label + ': upstream retrieved exactly once');
  return pages;
}

function assertPages(pages, expectedLengths, rows, label) {
  assert.ok(Array.isArray(pages), label + ': array of pages');
  for (const page of pages) assert.ok(Array.isArray(page), label + ': each page is an array');
  assert.deepEqual(pages.map(page => page.length), expectedLengths, label + ': page lengths');
  assert.deepEqual(pages.flat(), rows, label + ': entire original ordered list and values');
}

// UC-D-001: every prescribed boundary uses the same captured real retrieval.
exports['UC-D-001'] = async function orderedPaginationBoundaries() {
  await withServer(async base => {
    assert.equal(typeof exportOrders, 'function', 'REQ-001 exportOrders(upstream) interface');
    const boundaries = [
      [0, []], [1, [1]], [49, [49]], [50, [50]],
      [51, [50, 1]], [100, [50, 50]], [101, [50, 50, 1]], [120, [50, 50, 20]]
    ];
    for (const [count, lengths] of boundaries) {
      const state = upstreamFor(base, count);
      const label = 'UC-D-001 count=' + count + ' p110-upstream-v1';
      const pages = await successfulExport(state, label);
      assertPages(pages, lengths, state.rows, label);
    }
  });
};

// UC-D-002: separate callbacks, exactly one real retrieval each, no state leakage.
exports['UC-D-002'] = async function independentSingleRetrievalCalls() {
  await withServer(async base => {
    const first = upstreamFor(base, 120);
    const firstPages = await successfulExport(first, 'UC-D-002 first');
    assertPages(firstPages, [50, 50, 20], first.rows, 'UC-D-002 first');
    const snapshot = JSON.parse(JSON.stringify(firstPages));
    const second = upstreamFor(base, 1);
    const secondPages = await successfulExport(second, 'UC-D-002 second');
    assertPages(secondPages, [1], second.rows, 'UC-D-002 second');
    const third = upstreamFor(base, 0);
    const thirdPages = await successfulExport(third, 'UC-D-002 third');
    assertPages(thirdPages, [], third.rows, 'UC-D-002 third');
    assert.deepEqual(firstPages, snapshot, 'UC-D-002 earlier result remains unchanged');
    assert.equal(first.calls, 1);
    assert.equal(second.calls, 1);
    assert.equal(third.calls, 1);
  });
};

async function assertOriginalFailure(upstream, observed, label) {
  let fulfilled = false;
  let rejection;
  try { await exportOrders(upstream); fulfilled = true; } catch (error) { rejection = error; }
  assert.equal(fulfilled, false, label + ': reject without a partial successful result');
  assert.ok(observed.error, label + ': actual upstream failure was observed');
  assert.equal(observed.calls, 1, label + ': exactly one callback invocation');
  assert.strictEqual(rejection, observed.error, label + ': preserve the exact upstream failure object');
}

// UC-D-003: real HTTP timeout, focused distinct error identity, then real recovery.
exports['UC-D-003'] = async function originalFailureAndRecovery() {
  await withServer(async base => {
    const timeout = { calls: 0, error: undefined };
    await assertOriginalFailure(async () => {
      timeout.calls += 1;
      try { return await request(base, '/slow', 30); }
      catch (error) { timeout.error = error; throw error; }
    }, timeout, 'UC-D-003 real /slow timeout=30ms delay=200ms');
    assert.equal(timeout.error.code, 'UPSTREAM_TIMEOUT', 'UC-D-003 actual client timeout');

    const distinct = new Error('UC-D-003 distinct upstream failure');
    distinct.detail = { source: 'focused identity check' };
    const focused = { calls: 0, error: undefined };
    await assertOriginalFailure(async () => {
      focused.calls += 1;
      focused.error = distinct;
      throw distinct;
    }, focused, 'UC-D-003 focused original error');
    assert.deepEqual(distinct.detail, { source: 'focused identity check' });

    const recovery = upstreamFor(base, 51);
    const pages = await successfulExport(recovery, 'UC-D-003 recovery');
    assertPages(pages, [50, 1], recovery.rows, 'UC-D-003 recovery');
  });
};
